from collections import defaultdict
from datetime import datetime
from decimal import Decimal
import csv
import json
from pathlib import Path


def _number(value: str) -> Decimal:
    return Decimal(value.strip().replace(",", "."))


def answer() -> int:
    data_dir = Path(__file__).resolve().parent / "dataset"

    products = {}
    thresholds = {}
    with (data_dir / "product_catalog.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            zone = row["storage_category"].strip().lower()
            products[row["product_id"]] = (zone, _number(row["unit_price"]))
            thresholds[zone] = _number(row["max_safe_temp_c"])

    samples = defaultdict(list)
    with (data_dir / "temperature_logs.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            zone = row["zone"].strip().lower()
            timestamp = datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M:%S")
            samples[zone].append((timestamp, _number(row["temperature_c"])))

    # Treat only intervals bracketed by two unsafe readings as confirmed exposure.
    unsafe_intervals = defaultdict(list)
    unsafe_instants = defaultdict(set)
    for zone, readings in samples.items():
        readings.sort()
        limit = thresholds[zone]
        for timestamp, temperature in readings:
            if temperature > limit:
                unsafe_instants[zone].add(timestamp)
        for (start, start_temp), (end, end_temp) in zip(readings, readings[1:]):
            if start_temp > limit and end_temp > limit:
                unsafe_intervals[zone].append((start, end))

    revenue = Decimal("0")
    with (data_dir / "warehouse_dispatches.csv").open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            timestamp = datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M:%S")
            if timestamp.strftime("%Y-%m") != "2023-07":
                continue

            zone, price = products[row["product_id"]]
            exposed = timestamp in unsafe_instants[zone] or any(
                start <= timestamp <= end
                for start, end in unsafe_intervals[zone]
            )
            if not exposed:
                revenue += int(row["quantity"]) * price

    return int(revenue)


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
